-- Carga de 150 clientes ficticios distintos y sus pedidos para a base da livraria.
-- Inclui 100 ativos, 50 inativos e 113 clientes com pelo menos um pedido (75,3%).
-- CPFs são intencionalmente fictícios e inválidos; os e-mails de cadastro fictícios usam @gmail.com.
-- Execute após o schema e a carga_catalogo_livraria.sql; a carga cria a loja demonstrativa se ela ainda não existir.
USE livraria;
SET NAMES utf8;
START TRANSACTION;

INSERT INTO loja (nome, email, ativo) SELECT 'Livraria de Demonstracao - Carga', 'loja-carga@gmail.com', TRUE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM loja WHERE nome = 'Livraria de Demonstracao - Carga' AND ativo = TRUE);
SET @id_loja_carga := (SELECT id_loja FROM loja WHERE nome = 'Livraria de Demonstracao - Carga' AND ativo = TRUE ORDER BY id_loja LIMIT 1);

