) AS d
INNER JOIN cliente c ON c.email = d.email AND c.cpf = d.cpf
INNER JOIN pedidos p ON p.id_cliente = c.id_cliente AND p.id_loja = @id_loja_carga
    AND p.valor_total = d.valor_total AND p.status = d.status_pedido AND p.data_pedido = d.data_pedido
INNER JOIN livro li ON li.isbn = d.isbn
WHERE NOT EXISTS (
    SELECT 1 FROM item_pedido ip
    WHERE ip.id_pedido = p.id_pedido AND ip.id_livro = li.id_livro
);

